def _get_fernet() -> Fernet:
    return Fernet(load_master_key())


def encrypt(plaintext: dict) -> bytes:
    """dict -> JSON -> Fernet ciphertext bytes."""
    data = json.dumps(plaintext, ensure_ascii=False).encode()
    return _get_fernet().encrypt(data)


def decrypt(ciphertext: bytes) -> dict:
    """Fernet ciphertext -> JSON -> dict. Raises VaultError on failure."""
    try:
        raw = _get_fernet().decrypt(ciphertext)
        return json.loads(raw)
    except (InvalidToken, json.JSONDecodeError) as exc:
        raise VaultError(f"Failed to decrypt credentials: {exc}") from exc


def store_credentials(server_id: str, creds: dict) -> Path:
    """Encrypt and write credentials to secrets/servers/<server_id>.enc."""
    d = _secrets_dir()
    d.mkdir(parents=True, exist_ok=True)
    path = d / f"{server_id}.enc"
    path.write_bytes(encrypt(creds))
    path.chmod(0o600)
    return path


